//! Tests consume captures produced by the pinned Rust blobs-vectors binary.
//! Missing captures are a failure, never replaced by locally generated bytes.
const std = @import("std");
const t = std.testing;
const tree_mod = @import("bao_tree.zig");
const outboard_mod = @import("bao_outboard.zig");
const provider_mod = @import("provider.zig");
const getter = @import("getter.zig");
const requests = @import("requests.zig");
const framing = @import("framing.zig");
const postcard = @import("../wire/postcard.zig");
const range_spec = @import("range_spec.zig");
const store = @import("store.zig");

fn capture(comptime name: []const u8) ![]u8 {
    const file = try std.Io.Dir.cwd().openFile(
        t.io, "test/fixtures/blobs/" ++ name ++ ".bin", .{},
    );
    defer file.close(t.io);
    const length = try file.length(t.io);
    if (length > 1024 * 1024) return error.CaptureTooLarge;
    const bytes = try t.allocator.alloc(u8, @intCast(length));
    errdefer t.allocator.free(bytes);
    const read = try file.readPositionalAll(t.io, bytes, 0);
    if (read != bytes.len) return error.ShortCapture;
    return bytes;
}

test "pinned Store captures match Zig outboard requests provider and verified getter" {
    const data = try capture("data49189");
    defer t.allocator.free(data);
    try t.expectEqual(@as(usize, 49189), data.len);
    const root_bytes = try capture("root32");
    defer t.allocator.free(root_bytes);
    try t.expectEqual(@as(usize, 32), root_bytes.len);
    const root: [32]u8 = root_bytes[0..32].*;
    const tree = tree_mod.BaoTree.init(data.len);
    try t.expectEqual(root, try tree.rootHash(data));
    const outboard = try capture("outboard");
    defer t.allocator.free(outboard);
    var computed_outboard: [192]u8 = undefined;
    const outboard_len = try outboard_mod.encode(tree, data, &computed_outboard);
    try t.expectEqualSlices(u8, outboard, computed_outboard[0..outboard_len]);

    var tmp = try @import("test_scratch").tmpDir(.{});
    defer tmp.cleanup();
    var names: store.NameStorage = undefined;
    const paths = store.names(&names, root);
    const partial = try store.createPartial(t.io, tmp.dir, paths);
    try partial.data.writeStreamingAll(t.io, data);
    try partial.outboard.writeStreamingAll(t.io, outboard);
    partial.close(t.io);
    try store.commit(t.io, tmp.dir, paths);
    var scratch: [1024]u8 = undefined;
    const provider = try provider_mod.Provider.init(tmp.dir, &names, root, &scratch);

    inline for (.{ "all", "15-18", "47-49" }) |label| {
        const request_bytes = try capture("request-" ++ label);
        defer t.allocator.free(request_bytes);
        const response = try capture("response-" ++ label);
        defer t.allocator.free(response);
        var items: [8]range_spec.Item = undefined;
        var widths: [16]u64 = undefined;
        var room: requests.Storage = .{ .items = &items, .widths = &widths };
        var reader = postcard.Reader.init(request_bytes);
        const framed = try framing.Request.read(&reader, &room);
        try reader.finish();
        const request = switch (framed) {
            .to_eof => |value| switch (value) {
                .get => |get| get,
                else => return error.UnexpectedCaptureRequest,
            },
            else => return error.UnexpectedCaptureRequest,
        };
        var encoded_request: [256]u8 = undefined;
        var request_writer = postcard.Writer.init(&encoded_request);
        try framed.write(&request_writer, &.{});
        try t.expectEqualSlices(u8, request_bytes, request_writer.finish());
        var encoded_response: [49189 + 4096]u8 = undefined;
        var writer = std.Io.Writer.fixed(&encoded_response);
        try t.expectEqual(.answered, try provider.answer(t.io, &writer, request));
        try t.expectEqualSlices(u8, response, writer.buffered());
        var payload: [49189]u8 = undefined;
        const decoded = try getter.decode(request, tree.size, root, response, &payload);
        const start: usize = if (std.mem.eql(u8, label, "all")) 0 else if
            (std.mem.eql(u8, label, "15-18")) 15 * 1024 else 47 * 1024;
        const end: usize = if (std.mem.eql(u8, label, "15-18")) 18 * 1024 else data.len;
        try t.expectEqualSlices(u8, data[start..end], payload[0..decoded.written]);
        try t.expectError(error.SizeMismatch, getter.decode(
            request, tree.size + 1, root, response, &payload,
        ));
        const damaged = try t.allocator.dupe(u8, response);
        defer t.allocator.free(damaged);
        damaged[damaged.len - 1] ^= 1;
        try t.expectError(error.ChildMismatch, getter.decode(
            request, tree.size, root, damaged, &payload,
        ));
        if (getter.decode(request, tree.size, root, response[0 .. response.len - 1], &payload))
            |_| return error.TruncationAccepted
        else |err| try t.expect(err == error.ResponseTruncated or err == error.ProofIncomplete);
    }
}
